450|     /**
451|      * Writes a PAX extended header with the given map as contents.
452|      * @since 1.4
453|      */
454|     void writePaxHeaders(String entryName,
455|                          Map<String, String> headers) throws IOException {
456|         String name = "./PaxHeaders.X/" + stripTo7Bits(entryName);
457|             // TarEntry's constructor would think this is a directory
458|             // and not allow any data to be written
459|         if (name.length() >= TarConstants.NAMELEN) {
460|             name = name.substring(0, TarConstants.NAMELEN - 1);
461|         }
462|         TarArchiveEntry pex = new TarArchiveEntry(name,
463|                                                   TarConstants.LF_PAX_EXTENDED_HEADER_LC);
464| 
465|         StringWriter w = new StringWriter();
466|         for (Map.Entry<String, String> h : headers.entrySet()) {
467|             String key = h.getKey();
468|             String value = h.getValue();
469|             int len = key.length() + value.length()
470|                 + 3 /* blank, equals and newline */
471|                 + 2 /* guess 9 < actual length < 100 */;
472|             String line = len + " " + key + "=" + value + "\n";
473|             int actualLength = line.getBytes(CharsetNames.UTF_8).length;
474|             while (len != actualLength) {
475|                 // Adjust for cases where length < 10 or > 100
476|                 // or where UTF-8 encoding isn't a single octet
477|                 // per character.
478|                 // Must be in loop as size may go from 99 to 100 in
479|                 // first pass so we'd need a second.
480|                 len = actualLength;
481|                 line = len + " " + key + "=" + value + "\n";
482|                 actualLength = line.getBytes(CharsetNames.UTF_8).length;
483|             }
484|             w.write(line);
485|         }
486|         byte[] data = w.toString().getBytes(CharsetNames.UTF_8);
487|         pex.setSize(data.length);
488|         putArchiveEntry(pex);
489|         write(data);
490|         closeArchiveEntry();
491|     }
